REQUIRED = ('event_id', 'user_id', 'ts')
def assert_columns(df, required=REQUIRED):
    missing = set(required) - set(map(str, df.columns))
    if missing:
        raise ValueError(f'missing: {sorted(missing)}')
    return df

SELECT * FROM (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY ts DESC) rn
  FROM events
) WHERE rn = 1;

